import{_ as p,a0 as r,w as o,s as d,I as a,x as e,a1 as t,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"PostgreSQL 入門 | LCTT x X-CMD","titleTemplate":false,"description":"PostgreSQL 入門 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PostgreSQL 入門 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PostgreSQL 入門 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191112 Getting started with PostgreSQL","title":"PostgreSQL 入門","tag":"201911","desc":""},"relativePath":"201911/20191112 Getting started with PostgreSQL.md","filePath":"[post].md"}'),g={name:"201911/20191112 Getting started with PostgreSQL.md"};function h(c,s,k,u,b,f){const i=r("Link");return o(),d("div",null,[s[21]||(s[21]=a("h1",{id:"postgresql-入門",tabindex:"-1"},[e("PostgreSQL 入門 "),a("a",{class:"header-anchor",href:"#postgresql-入門","aria-label":"Permalink to “PostgreSQL 入門”"},"​")],-1)),s[22]||(s[22]=a("blockquote",null,[a("p",null,"安裝、設置、創建和開始使用 PostgreSQL 資料庫。")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201911/20/085936u10q7eme1euu4ak3.jpg",alt:""})],-1)),s[24]||(s[24]=a("p",null,"每個人或許都有需要在資料庫中保存的東西。即使你執着於使用紙質文件或電子文件，它們也會變得很麻煩。紙質文檔可能會丟失或混亂，你需要訪問的電子信息可能會隱藏在段落和頁面的深處。",-1)),a("p",null,[s[1]||(s[1]=e("在我從事醫學工作的時候，我使用 ",-1)),t(i,{href:"https://www.postgresql.org/"},{default:n(()=>[...s[0]||(s[0]=[e("PostgreSQL",-1)])]),_:1}),s[2]||(s[2]=e(" 來跟蹤我的住院患者名單並提交有關住院患者的信息。我將我的每日患者名單打印在口袋裏，以便快速瞭解患者房間、診斷或其他細節的任何變化並做出快速記錄。",-1))]),s[25]||(s[25]=l('<p>我以為一切沒問題，直到去年我妻子決定買一輛新車，我“接手”了她以前的那輛車。她保留了汽車維修和保養服務收據的文件夾，但隨着時間的流逝，它變得雜亂。與其花時間篩選所有紙條以弄清楚什麼時候做了什麼，我認為 PostgreSQL 將是更好的跟蹤此信息的方法。</p><h3 id="安裝-postgresql" tabindex="-1">安裝 PostgreSQL <a class="header-anchor" href="#安裝-postgresql" aria-label="Permalink to “安裝 PostgreSQL”">​</a></h3><p>自上次使用 PostgreSQL 以來已經有一段時間了，我已經忘記了如何使用它。實際上，我甚至沒有在計算機上安裝它。安裝它是第一步。我使用 Fedora，因此在控制台中運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf list postgresql*</span></span></code></pre></div><p>請注意，你無需使用 <code>sudo</code> 即可使用 <code>list</code> 選項。該命令返回了很長的軟件包列表。看了眼後，我決定只需要三個：postgresql、postgresql-server 和 postgresql-docs。</p>',5)),a("p",null,[s[4]||(s[4]=e("為了瞭解下一步需要做什麼，我決定查看 ",-1)),t(i,{href:"http://www.postgresql.org/docs"},{default:n(()=>[...s[3]||(s[3]=[e("PostgreSQL 文檔",-1)])]),_:1}),s[5]||(s[5]=e("。文檔參考內容非常豐富，實際上，豐富到令人生畏。幸運的是，我發現我在升級 Fedora 時曾經做過的一些筆記，希望有效地導出資料庫，在新版本上重新啓動 PostgreSQL，以及導入舊資料庫。",-1))]),s[26]||(s[26]=l(`<h3 id="設置-postgresql" tabindex="-1">設置 PostgreSQL <a class="header-anchor" href="#設置-postgresql" aria-label="Permalink to “設置 PostgreSQL”">​</a></h3><p>與大多數其他軟件不同，你不能只是安裝好 PostgreSQL 就開始使用它。你必須預先執行兩個基本步驟：首先，你需要設置 PostgreSQL，第二，你需要啓動它。你必須以 <code>root</code> 用户身份執行這些操作（<code>sudo</code> 在這裏不起作用）。</p><p>要設置它，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>postgresql-setup –initdb</span></span></code></pre></div><p>這將確定 PostgreSQL 資料庫在計算機上的位置。然後（仍為 <code>root</code>）輸入以下兩個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start postgresql.service</span></span>
<span class="line"><span>systemctl enable postgresql.service</span></span></code></pre></div><p>第一個命令為當前會話啓動 PostgreSQL（如果你關閉機器，那麼 PostgreSQL 也將關閉）。第二個命令使 PostgreSQL 在隨後的重啓中自動啓動。</p><h3 id="創建用户" tabindex="-1">創建用户 <a class="header-anchor" href="#創建用户" aria-label="Permalink to “創建用户”">​</a></h3><p>PostgreSQL 正在運行，但是你仍然不能使用它，因為你還沒有用户。為此，你需要切換到特殊用户 <code>postgres</code>。當你仍以 <code>root</code> 身份運行時，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>su postgres</span></span></code></pre></div><p>由於你是以 <code>root</code> 的身份執行此操作的，因此無需輸入密碼。root 用户可以在不知道密碼的情況下以任何用户身份操作；這就是使其強大而危險的原因之一。</p><p>現在你就是 <code>postgres</code> 了，請運行下面兩個命令，如下所示創建用户（創建用户 <code>gregp</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>createuser gregp</span></span>
<span class="line"><span>createdb gregp</span></span></code></pre></div><p>你可能會看到錯誤消息，如：<code>Could not switch to /home/gregp</code>。這只是意味着用户 <code>postgres</code>不能訪問該目錄。儘管如此，你的用户和資料庫已創建。接下來，輸入 <code>exit</code> 並按回車兩次，這樣就回到了原來的用户下（<code>root</code>）。</p><h3 id="設置資料庫" tabindex="-1">設置資料庫 <a class="header-anchor" href="#設置資料庫" aria-label="Permalink to “設置資料庫”">​</a></h3><p>要開始使用 PostgreSQL，請在命令列輸入 <code>psql</code>。你應該在每行左側看到類似 <code>gregp=&gt;</code> 的內容，以顯示你使用的是 PostgreSQL，並且只能使用它理解的命令。你自動獲得一個數據庫（我的名為 <code>gregp</code>），它裏面完全沒有內容。對 PostgreSQL 來説，資料庫只是一個工作空間。在空間內，你可以創建<em>表</em>。表包含變量列表，而表中的每個變量是構成資料庫的數據。</p><p>以下是我設置汽車服務資料庫的方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE autorepairs (</span></span>
<span class="line"><span>        date            date,</span></span>
<span class="line"><span>        repairs         varchar(80),</span></span>
<span class="line"><span>        location        varchar(80),</span></span>
<span class="line"><span>        cost            numeric(6,2)</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>我本可以在一行內輸入，但為了更好地説明結構，並表明 PostgreSQL 不會解釋製表符和換行的空白，我分成了多行。字段包含在括號中，每個變量名和數據類型與下一個變量用逗號分隔（最後一個除外），命令以分號結尾。所有命令都必須以分號結尾！</p><p>第一個變量名是 <code>date</code>，它的數據類型也是 <code>date</code>，這在 PostgreSQL 中沒關係。第二個和第三個變量 <code>repairs</code> 和 <code>location</code> 都是 <code>varchar(80)</code> 類型，這意味着它們可以是最多 80 個任意字符（字母、數字等）。最後一個變量 <code>cost</code> 使用 <code>numeric</code> 類型。括號中的數字表示最多有六位數字，其中兩位是小數。最初，我嘗試了 <code>real</code> 類型，這將是一個浮點數。<code>real</code> 類型的問題是作為數據類型在使用時，在遇到 <code>WHERE</code> 子句，類似 <code>WHERE cost = 0</code> 或其他任何特定數字。由於 <code>real</code> 值有些不精確，因此特定數字將永遠不會匹配。</p><h3 id="輸入數據" tabindex="-1">輸入數據 <a class="header-anchor" href="#輸入數據" aria-label="Permalink to “輸入數據”">​</a></h3><p>接下來，你可以使用 <code>INSERT INTO</code> 命令添加一些數據（在 PostgreSQL 中稱為<em>行</em>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INSERT INTO autorepairs VALUES (&#39;2017-08-11&#39;, &#39;airbag recall&#39;, &#39;dealer&#39;, 0);</span></span></code></pre></div><p>請注意，括號構成了一個值的容器，它必須以正確的順序，用逗號分隔，並在命令末尾加上分號。<code>date</code> 和 <code>varchar(80)</code> 類型的值必須包含在單引號中，但數字值（如 <code>numeric</code>）不用。作為反饋，你應該會看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INSERT 0 1</span></span></code></pre></div><p>與常規終端會話一樣，你會有輸入命令的歷史記錄，因此，在輸入後續行時，通常可以按向上箭頭鍵來顯示最後一個命令並根據需要編輯數據，從而節省大量時間。</p><p>如果出了什麼問題怎麼辦？使用 <code>UPDATE</code> 更改值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UPDATE autorepairs SET date = &#39;2017-11-08&#39; WHERE repairs = &#39;airbag recall&#39;;</span></span></code></pre></div><p>或者，也許你不再需要表中的行。使用 <code>DELETE</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE FROM autorepairs WHERE repairs = &#39;airbag recall&#39;;</span></span></code></pre></div><p>這將刪除整行。</p><p>最後一件事：即使我在 PostgreSQL 命令中一直使用大寫字母（在大多數文檔中也這麼做），你也可以用小寫字母輸入，我也經常如此。</p><h3 id="輸出數據" tabindex="-1">輸出數據 <a class="header-anchor" href="#輸出數據" aria-label="Permalink to “輸出數據”">​</a></h3><p>如果你想展示數據，使用 <code>SELECT</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT * FROM autorepairs ORDER BY date;</span></span></code></pre></div><p>沒有 <code>ORDER BY</code> 的話，行將不管你輸入的內容來顯示。例如，以下就是我終端中輸出的我的汽車服務數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT date, repairs FROM autorepairs ORDER BY date;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    date   |                             repairs                             </span></span>
<span class="line"><span>-----------+-----------------------------------------------------------------</span></span>
<span class="line"><span>2008-08-08 | oil change, air filter, spark plugs</span></span>
<span class="line"><span>2011-09-30 | 35000 service, oil change, rotate tires/balance wheels</span></span>
<span class="line"><span>2012-03-07 | repl battery</span></span>
<span class="line"><span>2012-11-14 | 45000 maint, oil/filter</span></span>
<span class="line"><span>2014-04-09 | 55000 maint, oil/filter, spark plugs, air/dust filters</span></span>
<span class="line"><span>2014-04-21 | replace 4 tires</span></span>
<span class="line"><span>2014-04-21 | wheel alignment</span></span>
<span class="line"><span>2016-06-01 | 65000 mile service, oil change</span></span>
<span class="line"><span>2017-05-16 | oil change, replce oil filt housing</span></span>
<span class="line"><span>2017-05-26 | rotate tires</span></span>
<span class="line"><span>2017-06-05 | air filter, cabin filter,spark plugs</span></span>
<span class="line"><span>2017-06-05 | brake pads and rotors, flush brakes</span></span>
<span class="line"><span>2017-08-11 | airbag recall</span></span>
<span class="line"><span>2018-07-06 | oil/filter change, fuel filter, battery svc</span></span>
<span class="line"><span>2018-07-06 | transmission fl, p steering fl, rear diff fl</span></span>
<span class="line"><span>2019-07-22 | oil &amp;amp; filter change, brake fluid flush, front differential flush</span></span>
<span class="line"><span>2019-08-20 | replace 4 tires</span></span>
<span class="line"><span>2019-10-09 | replace passenger taillight bulb</span></span>
<span class="line"><span>2019-10-25 | replace passenger taillight assembly</span></span>
<span class="line"><span>(19 rows)</span></span></code></pre></div><p>要將此發送到文件，將輸出更改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\o autorepairs.txt</span></span></code></pre></div><p>然後再次運行 <code>SELECT</code> 命令。</p><h3 id="退出-postgresql" tabindex="-1">退出 PostgreSQL <a class="header-anchor" href="#退出-postgresql" aria-label="Permalink to “退出 PostgreSQL”">​</a></h3><p>最後，在終端中退出 PostgreSQL，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>quit</span></span></code></pre></div><p>或者它的縮寫版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\q</span></span></code></pre></div><p>雖然這只是 PostgreSQL 的簡要介紹，但我希望它展示了將資料庫用於這樣的簡單任務既不困難也不費時。</p><hr>`,47)),a("p",null,[s[7]||(s[7]=e("via: ",-1)),t(i,{href:"https://opensource.com/article/19/11/getting-started-postgresql"},{default:n(()=>[...s[6]||(s[6]=[e("https://opensource.com/article/19/11/getting-started-postgresql",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=e("作者：",-1)),t(i,{href:"https://opensource.com/users/greg-p"},{default:n(()=>[...s[8]||(s[8]=[e("Greg Pittman",-1)])]),_:1}),s[13]||(s[13]=e(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[9]||(s[9]=[e("lujun9972",-1)])]),_:1}),s[14]||(s[14]=e(" 譯者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[10]||(s[10]=[e("geekpi",-1)])]),_:1}),s[15]||(s[15]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[e("Linux中國",-1)])]),_:1}),s[20]||(s[20]=e(" 榮譽推出",-1))])])}const S=p(g,[["render",h]]);export{P as __pageData,S as default};
